ALTER TABLE `freight_rate_tables` ADD COLUMN `notes` TEXT NULL, ADD COLUMN `previous_version_id` CHAR(36) NULL, ADD INDEX `freight_rate_tables_previous_version_idx` (`tenant_id`,`previous_version_id`), ADD CONSTRAINT `freight_rate_tables_previous_version_fk` FOREIGN KEY (`previous_version_id`) REFERENCES `freight_rate_tables` (`id`) ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE `freight_rate_table_coverages` (`id` CHAR(36) NOT NULL, `tenant_id` CHAR(36) NOT NULL, `rate_table_id` CHAR(36) NOT NULL, `coverage_id` CHAR(36) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `freight_rate_table_coverages_unique` (`tenant_id`,`rate_table_id`,`coverage_id`), KEY `freight_rate_table_coverages_coverage_idx` (`tenant_id`,`coverage_id`), CONSTRAINT `freight_rate_table_coverages_table_fk` FOREIGN KEY (`rate_table_id`) REFERENCES `freight_rate_tables` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `freight_rate_table_coverages_coverage_fk` FOREIGN KEY (`coverage_id`) REFERENCES `carrier_coverages` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
